mapper.select:
SELECT analysis_id AS id,audio_path AS audioPath FROM speech_analyses
WHERE audio_path IS NOT NULL AND audio_expires_at IS NOT NULL AND audio_expires_at <= CURRENT_TIMESTAMP
  AND audio_delete_attempts < #{maxAttempts}
ORDER BY audio_expires_at LIMIT #{limit}

SELECT message_id AS id,audio_path AS audioPath FROM conversation_messages
WHERE audio_path IS NOT NULL AND created_at <= DATE_SUB(CURRENT_TIMESTAMP, INTERVAL #{retentionMonths} MONTH)
ORDER BY created_at LIMIT #{limit}
